import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/12-How-to-spot-the-robot-spy-next-to-you.html","title":"13-怎样找出身边的机器人间谍？","lang":"zh-CN","frontmatter":{"title":"13-怎样找出身边的机器人间谍？","icon":"read","date":"2025-04-15T13:47:44.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1744696920000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":10,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":3}],"changelog":[{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"e6a89270c9a18c4e480e6a31a78e7bd19ee0aa9d","time":1744696348000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"9e64ca1deee70fc5ffd4b2aee88123ab532011af","time":1744341966000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"headerDepth: 5"},{"hash":"b791eda7e4ee96ed6ef5092645b5c23d4bc49a52","time":1744340684000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"02-如何用编程思维抓住机器人间谍？"},{"hash":"ed6b716374e0d1f67e2e9c7a07798bb77547ad9a","time":1744336771000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"在我的这门编程思维课里，我不会直接教你怎么写代码，而是会教给你编程的思维，帮你换个角度思考问题。"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"d2f6408645561f94a1456e9fdbbcf5759ad6dcdd","time":1675746146000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"优化"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":9.36,"words":2807},"filePathRelative":"column/Programmingthinking/12-How-to-spot-the-robot-spy-next-to-you.md"}`),a={name:`12-How-to-spot-the-robot-spy-next-to-you.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>在我的这门编程思维课里，我不会直接教你怎么写代码，而是会教给你编程的思维，帮你换个角度思考问题。</p><p>这一讲，我就会教你用编程思维干一件厉害的事情，<strong>抓机器人间谍</strong>。</p><p>在好多科幻电影里，都有特别厉害的人工智能或者是机器人，比方说，电影《复仇者联盟》里就有<strong>邪恶人工智能奥创</strong>。电影《终结者》里面，也有能伪装成人类的<strong>机器人杀手</strong>。</p><p>其实，在我们的现实生活中，科学家也造出了和人类特别像的机器人，光看外表确实有点区分不出哪个是机器人，哪个是真人。</p><p>那你有没有想过，如果有一天，我们身边混入了一台人型机器人，而且还是一台邪恶的机器人，那我们有什么办法能把它找出来呢？</p><p>诶，还真有办法。这就要说到一个词，叫做“<strong>图灵测试</strong>”。如果你喜欢看科幻故事，可能听说过这个词。在科幻故事里，要是一个机器人通过了图灵测试，那可不得了，这就说明它能和咱们人类一样思考，可以成为一个<strong>超级AI</strong>了。</p><p>那到底什么是图灵测试呢？今天，我会借着一部叫做<strong>《机械姬》</strong>的电影，给你讲一讲。</p><figure><img src="/assets/df43cb405f1353b889ec4b7249644bf3-BZP1fSYO.png" alt="《机械姬》电影海报" tabindex="0" loading="lazy"><figcaption>《机械姬》电影海报</figcaption></figure><p>故事的主角叫做<strong>史密斯</strong>，是一位<strong>程序员</strong>，在一家特别厉害的科技公司工作。有一天呢，这个公司搞了一个内部的抽奖活动。恰巧，史密斯就抽到了头号大奖，获得了和老板共度周末的机会，这可把他高兴坏了。</p><figure><img src="/assets/5c2bc7ed37a203d242e8ae5ffa32b89d-CQ8dRfsa.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你可能要问了，跟老板共度周末有什么好高兴的？在公司不是天天能见着老板吗？还真不是，这个公司的老板<strong>神神秘秘</strong>的，不轻易露面。而且这个老板特别厉害，算得上是一位<strong>人工智能专家</strong>了，要是能跟他共度周末，估计能学不少东西呢。</p><p>赢得这个大奖，史密斯当然也很高兴了，开开心心就来到了老板的别墅里。等见到老板之后，老板就跟史密斯说：“恭喜你中奖了，不过我请你过来不是来玩的，我想请你帮我做一件事。”</p><p>听起来像是个<strong>秘密任务</strong>啊，能被选中参与这样一个秘密项目，史密斯就更激动啦。那是什么任务呢？</p><p>老板接着说了：“我造了一个机器人，名叫<strong>艾娃</strong>。她可能拥有了<strong>人类的智慧</strong>，但是，我说了不算，你来给它做一个图灵测试吧。看她是不是真的有智慧。”</p><p>你看，老板也提到了图灵测试，那到底什么是图灵测试呢？</p><figure><img src="/assets/5fb0450e04f3128d4ca9706d47211482-CQOpitwv.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>图灵是一个科学家的名字。图灵测试呢，就是他提出来的。这个图灵特别厉害，被称作人工智能之父，在后面，我还会详细给你说他的故事。</p><p>那什么是图灵测试呢？原理并不复杂。</p><p>假如有两个房间，一个房间里是人，另一个里头是机器人。你不在房间里，也看不见房间里的情况，<strong>只能通过打字</strong>，跟房间里的人或者是机器人交流，然后<strong>判断</strong>出来哪个房间里是人类，哪个房间里是机器人。</p><p>当然了，这个机器人在回答问题的时候，会想办法<strong>伪装</strong>成人类。假如问了一堆问题之后，你还是分不清谁是人类谁是机器人，图灵就认为，这个机器人通过了测试，它是拥有智慧的。</p><p>所以，在《机械姬》这个电影里，老板就想通过图灵测试，证明自己造的机器人艾娃是有智慧的。那我请你想象一下，假如你是史密斯，老板让你给艾娃做图灵测试，你想问什么问题呢？</p><p>你可能会想，咱们人类和机器人有一个很明显的差别，那就是咱们<strong>人类有感情，机器人只知道执行命令，是没有感情的</strong>。所以咱们可以问艾娃比较感性的问题，比如，“你喜欢看什么电影啊？”“电影里哪个情节最打动你？”</p><p>这个思路倒是没错，但麻烦的是，机器人艾娃本质上是一台电脑，她是可以上网的啊，网络上有那么多人写电影评价，为了伪装成人类，她可以随便<strong>复制</strong>一段讲给你听嘛。</p><p>那要是问一些更难的问题呢？比如问她：人生的意义是什么呀？机器人没事肯定不会想这个问题吧？可同样的，艾娃还是可以从网上找一段别人的回答，讲给你听。</p><p>再说了，像是“人生的意义”这样的问题，你如果去问一个真人，他很可能也回答不好，或者干脆给你来个答非所问，让你觉得，诶，这个话里好像有玄机。那如果机器人艾娃也给出了一个看起来充满玄机的答案，你又该怎么评价呢？这么看来，好像陷入了死胡同。</p><p>别着急，这个时候，就要有请<strong>编程思维</strong>出场了。在编程思维里最重要的一步就是搞清楚我们的目标。这就好比是做一道数学题首先得理解题意一样，咱们做这个图灵测试，不是为了难倒机器人，而是为了判断出和自己说话的到底是人还是机器人，对吧？</p><p>咱们前面找的那些问题，是想难住机器人，让人类答出来。既然这条思路行不通，那能不能<strong>倒过来想</strong>呢？难不倒机器人，我们能不能<strong>难倒人类</strong>呢？这样不也能区分出来谁是人类谁是机器人吗？</p><p>你可能觉得，机器人都是我们人类造的，它们怎么会比我们还厉害？诶，你可别忘了，机器人的本质是一台计算机。它们查询各种信息的速度可比我们快多了。</p><p>打个比方吧，你可以问对方：“你喜欢看‘<strong>哈利·波特</strong>’吗？”</p><p>对方只要说：“当然喜欢了。”</p><p>那接下来你就可以问了：“那你说说‘哈利·波特’第七部，第三章正文里面第11个字是什么呢？”</p><p>如果对方是个人类，无论他有多喜欢“哈利·波特”，都没法一下子答上来吧？搞不好还会说：“你疯了吧，谁会知道这样的事情。”</p><p>但如果对方是机器人，它可能想都不想，马上就告诉你那个字是啥——诶，这就太可疑了，对吧？</p><p>另外，在做数学计算上，计算机也比咱们人脑快很多很多，你要是问对方8346×5639等于几？要是对方想都不想，答案脱口而出，那这家伙肯定也是个机器人。</p><p>这种倒过来想问题的方法，又被叫做<strong>逆向思维或者叫逆推法</strong>。在你学习中也很容易用上。</p><p>比方说，你可能碰到过一类数学题，问你一个数字，加上10，乘以10，减去10，除以10之后，还是10，问你这个数字是几。这时候，你用逆推法，倒着算一遍就特别容易算出答案是1，感兴趣的话你可以动手试一试。</p><figure><img src="data:image/png;base64," alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>当然了，除了在学习上，在咱们的生活中，逆向思维也特别有用。比方说，你肯定拍过<strong>大合照</strong>吧？好几十个人在一起拍照片，在按下快门的时候，难免会有人闭上了眼睛。</p><p>怎么办呢？按照常规思路，当然是大家都撑着尽量别眨眼对吧？但咱们可以倒过来想，如果大家<strong>先把眼睛闭上</strong>，等到拍照前一秒同时把眼睛睁开，这样一来，就不容易出现有人闭眼睛的情况了。这也是逆向思维的运用。</p><p>那咱们还是说回电影，艾娃有没有通过图灵测试呢？她当然通过了，而且她的智慧不仅能<strong>通过图灵测试</strong>，还把史密斯和老板都给骗了，怎么回事呢？</p><p>在电影里，艾娃趁着史密斯给自己做图灵测试的机会，和史密斯聊了起来，而且还说服了史密斯帮自己逃跑。</p><p>其实，老板也不傻，他知道自己造的艾娃有多聪明，还预料到艾娃说不定会想逃跑，所以给整个实验室，也就是他的别墅，设置了<strong>严格的安保系统</strong>。在看到艾娃和史密斯商量逃跑计划的时候，老板并没有太在意，反而特别高兴。</p><p>老板高兴什么呢？</p><p>原来，老板制造艾娃的时候，从来没有给她植入过什么程序，让她想逃跑。如果艾娃产生了这样的想法，岂不是说明她<strong>拥有了自己的意志</strong>？</p><p>而且，艾娃能主动去设计整个逃跑计划，还能说服史密斯帮自己实施计划，这已经不是通过图灵测试这么简单了，可以说机器人艾娃已经是<strong>相当聪明</strong>了。</p><p>老板就觉得，自己能造出这样的机器人，肯定会受到所有专家的认可。但老板却有些自负了，他坚信艾娃不可能打破自己设置的安保系统。这个自负，给老板带来了危险。</p><p>一次，艾娃趁老板喝醉酒的机会，让史密斯修改了实验室的安保程序。结果就可想而知了，艾娃<strong>成功逃出了实验室</strong>，还杀死了老板，把史密斯一个人关在了实验室里面。逃出去的艾娃会做什么呢？电影故事里并没有说，但想想有些可怕，是吧？</p><p>那听到这你肯定要问了，咱们现实生活中肯定没有通过图灵测试的机器人吧？我要告诉你，还真有，早在2014年——那时候，你可能才刚刚出生，就有机器人通过了图灵测试。</p><p>诶呀，那这些机器人会不会像艾娃一样逃出实验室呢？会不会在咱们的身边，已经隐藏着好多仇恨人类的机器人呢？这些问题我会在后面的课程里给你解答，欢迎你加入我的课程，用编程思维去应对未来的挑战！</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};